content.text:
The evidence supports one root cause: checkout's outgoing calls to payment are held back by about 440 ms at the HTTP/gRPC layer, while payment's server span stays normal and checkout's other outgoing calls are unchanged. The delay travels checkout → frontend → frontend-proxy and ends in user requests.

```json
{
  "root_causes": [
    {
      "service": "checkout",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(min(duration)/1e6,1) min_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge'",
          "claim": "In abnormal period, checkout's PaymentService/Charge client spans take about 442 ms each (min 441 ms)."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' src, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms FROM normal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge' UNION ALL SELECT 'abnormal', count(*), round(approx_quantile(duration,0.5)/1e6,1) FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge'",
          "claim": "Charge client p50 rose from about 2.6 ms in normal period to about 442 ms in abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' src, round(approx_quantile(duration,0.5)/1e6,2) p50_ms, round(approx_quantile(duration,0.95)/1e6,2) p95_ms FROM normal_traces WHERE service_name='payment' AND span_name='grpc.oteldemo.PaymentService/Charge' UNION ALL SELECT 'abnormal', round(approx_quantile(duration,0.5)/1e6,2), round(approx_quantile(duration,0.95)/1e6,2) FROM abnormal_traces WHERE service_name='payment' AND span_name='grpc.oteldemo.PaymentService/Charge'",
          "claim": "Payment's own Charge server span stays about 1.2 ms in both periods, so the delay is before the payment handler."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,2) p50_ms, round(approx_quantile(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind='Client' AND span_name IN ('oteldemo.CartService/GetCart','oteldemo.CurrencyService/Convert','HTTP POST') GROUP BY span_name",
          "claim": "Checkout's other outgoing calls (cart, currency, shipping HTTP POST) keep normal latency in the abnormal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH ck AS (SELECT DISTINCT trace_id FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge') SELECT t.service_name, t.span_name, round(t.duration/1e6,1) ms FROM abnormal_traces t JOIN ck USING(trace_id) WHERE t.service_name='frontend' AND t.attr_span_kind='Server'",
          "claim": "Traces containing the slow checkout Charge call show the frontend POST server span at about 15 s."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH ck AS (SELECT DISTINCT trace_id FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge') SELECT t.service_name, t.span_name, t.attr_http_response_status_code code, round(t.duration/1e6,1) ms FROM abnormal_traces t JOIN ck USING(trace_id) WHERE t.service_name='frontend-proxy' AND t.span_name='ingress'",
          "claim": "The same traces show frontend-proxy ingress spans around 15 s, carrying the stalled checkout request to users."
        }
      ]
    }
  ]
}
```

